import java.io.*;
import java.util.*;

public class Main {
    private static int countPossibilities(char[] s, char x) {
        for(int i = 0; i < s.length; i++) {
            if(s[i] == 'X') s[i] = x;
        }
        if(s[0] == '0') return 0;
        int possibilities = 1;
        boolean firstXSeen = true;
        for(int i = 0; i < s.length; i++) {
            if(s[i] == '_') {
                possibilities *= (i == 0) ? 9 : 10;
            } else if(s[i] == 'X' && firstXSeen) {
                possibilities *= (i == 0) ? 9 : 10;
                firstXSeen = false;
            }
        }
        return possibilities;
    }
    private static boolean checkReplacementValidity(char[] s, char a, char b) {
        if(s[s.length-2] >= '0' && s[s.length-2] <= '9' && s[s.length-2] != a) return false;
        if(s[s.length-1] >= '0' && s[s.length-1] <= '9' && s[s.length-1] != b) return false;
        if(s[s.length-2] == 'X' && s[s.length-1] == 'X' && a != b) return false;
        return true;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
        char[] s = br.readLine().toCharArray();
        if(s.length < 2) {
            pw.println((s[0] == '0' || s[0] == '_' || s[0] == 'X') ? 1 : 0);
        } else {
            int totalOptions = 0;
            if(checkReplacementValidity(s, '0', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '0';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    totalOptions += countPossibilities(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    totalOptions += countPossibilities(t, t[t.length-1]);
                } else {
                    totalOptions += countPossibilities(t, 'X');
                }
            }
            if(checkReplacementValidity(s, '2', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '2';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    totalOptions += countPossibilities(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    totalOptions += countPossibilities(t, t[t.length-1]);
                } else {
                    totalOptions += countPossibilities(t, 'X');
                }
            }
            if(checkReplacementValidity(s, '5', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '5';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    totalOptions += countPossibilities(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    totalOptions += countPossibilities(t, t[t.length-1]);
                } else {
                    totalOptions += countPossibilities(t, 'X');
                }
            }
            if(checkReplacementValidity(s, '7', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '7';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    totalOptions += countPossibilities(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    totalOptions += countPossibilities(t, t[t.length-1]);
                } else {
                    totalOptions += countPossibilities(t, 'X');
                }
            }
            pw.println(totalOptions);
        }
        br.close();
        pw.close();
    }
}
